-- Resources content for seeding active copy from RadioTraffic (CLAUDE.md,
-- "Resources stay in step with the code"; docs/underwriting-traffic-
-- redesign.md §15). Content only: the copy migration needs no schema change.

select private.rc_release_guide(
  p_slug => 'underwriting-migrate-legacy-copy',
  p_tool_key => 'underwriting',
  p_title => 'Migrate legacy copy',
  p_summary => 'Bring active copy in from a RadioTraffic export, answer what it can''t decide on its own, and import.',
  p_screen_keys => array['underwriting.migration-copy'],
  p_sort_order => 91,
  p_version_note => 'First version',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Administrators use this screen once, to bring the station's active underwriting copy in from RadioTraffic. Open it from the Contracts list ("},{"type":"text","text":"Migrate legacy records","marks":[{"type":"bold"}]},{"type":"text","text":", then the "},{"type":"text","text":"Copy","marks":[{"type":"bold"}]},{"type":"text","text":" tab) or from the Copy library ("},{"type":"text","text":"Import from RadioTraffic","marks":[{"type":"bold"}]},{"type":"text","text":")."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Choose the export"}]},{"type":"paragraph","content":[{"type":"text","text":"In RadioTraffic's “Active Copy by Underwriter” workbook, use File › Save As › CSV, then choose that file. Title lines above the header row are fine. Columns are found by name: Underwriter, Copy Name, Cart, Length, Start Date, End Date and Script. Nothing is written until you import."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Review"}]},{"type":"paragraph","content":[{"type":"text","text":"Most rows need nothing from you. The screen leads with the few questions it can't answer on its own, each with a short set of choices:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"New underwriter","marks":[{"type":"bold"}]},{"type":"text","text":": a name that isn't on file. Add it, choose the underwriter it really is, or leave its rows out."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Which contract","marks":[{"type":"bold"}]},{"type":"text","text":": more than one agreement covers the copy's dates, or the copy is for a product (a Learning Minute) no agreement is for. The answer covers all of that underwriter's copy, so a rotation is never split between contracts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Which flight","marks":[{"type":"bold"}]},{"type":"text","text":": event copy whose name fits more than one flight."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Changed wording","marks":[{"type":"bold"}]},{"type":"text","text":": the portal has copy with the same name and cart but different words. Where the difference is a few characters, the portal's copy is usually the damaged one and using RadioTraffic's wording is recommended; where the portal filled in a spot number RadioTraffic leaves blank, keeping the portal's is. A genuinely new message is added as its own copy. The portal's copy is only changed when you choose it."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A recommended answer is already chosen and shown folded, with Change beside it. Rows waiting on an unanswered question stay out of the import; everything else can come in now."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How rows are matched"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An underwriter is matched by name, ignoring punctuation, apostrophes, “&” and plurals. A few names RadioTraffic spells differently, such as the FPM accounts, are matched from a fixed list."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Copy already in the portal is recognised by its script, however it got there, and reused. Its dates are set to RadioTraffic's; a missing cart is added. Nothing else about it changes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"New copy comes in approved, with RadioTraffic's dates. A script that asks the host to play a recorded spot is stored as recorded, at the export's length; anything read aloud is a live read, planned at its read time. The cart number is kept as RadioTraffic's reference."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Copy is linked to a contract only when exactly one current agreement fits its dates. App and digital agreements are never used for broadcast copy. Event copy is scoped to the flight it names. Linked copy joins that contract's rotation; copy with no agreement stays with its underwriter and can be linked later from the contract's Copy tab."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Placeholders (“copy holder”) and rows that aren't underwriting copy, such as the EAS test, are left out. WUWF Day Sponsor copy comes in under its own underwriter with no contract."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Running it again"}]},{"type":"paragraph","content":[{"type":"text","text":"It is safe to run the same export again, or a newer one. Copy already here is recognised and skipped, links that exist are left alone, and a message that failed the first time is picked up. Each import is recorded in the audit log."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'underwriting-migrate-legacy-agreements',
  p_tool_key => 'underwriting',
  p_title => 'Migrate legacy agreements',
  p_summary => 'Load a manifest of existing agreements, match each to its signed document, import them as draft contracts, and review the results.',
  p_screen_keys => array['underwriting.migration'],
  p_sort_order => 90,
  p_version_note => 'Opened from Migrate legacy records, which now has a Copy tab',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Administrators use this screen to bring agreements from the station's legacy records into Underwriting & Traffic. Open it from the Contracts list: "},{"type":"text","text":"Migrate legacy records","marks":[{"type":"bold"}]},{"type":"text","text":". It lists every batch with how far along it is and what it needs next."},{"type":"text","text":" Agreements are the first of its two tabs; active copy from RadioTraffic comes in on the second, Copy."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Start a batch"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"New batch","marks":[{"type":"bold"}]},{"type":"text","text":", name the batch, and choose where the facts come from: "},{"type":"text","text":"A spreadsheet of agreements","marks":[{"type":"bold"}]},{"type":"text","text":" (recommended) or "},{"type":"text","text":"Documents only","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For a spreadsheet, choose the manifest CSV or paste its rows. Every row is checked before anything is saved. A row that can't be read, or whose sponsor isn't on file, is listed first. When a close name is on file, select "},{"type":"text","text":"Use it","marks":[{"type":"bold"}]},{"type":"text","text":"; otherwise add the underwriter under Underwriters and load the manifest again."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Load and continue","marks":[{"type":"bold"}]},{"type":"text","text":". Rows that still need a fix are left out."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The manifest needs the underwriter and the document's file name in each row; the order number, run dates, sponsorship total, contract type, Drive file id, documentation status, and notes are optional. "},{"type":"text","text":"Download a template","marks":[{"type":"bold"}]},{"type":"text","text":" gives the column names."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Choose the documents"}]},{"type":"paragraph","content":[{"type":"text","text":"Choose the folder of signed agreements. Each entry is matched to its file by name. Anything that didn't match cleanly is listed under "},{"type":"text","text":"Needs attention","marks":[{"type":"bold"}]},{"type":"text","text":" with what to do: use a close match, choose the file, pick which entry a shared file belongs to, or choose a copy under 10 MB. Files the manifest doesn't name can be imported too, with every fact read from the document."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Import"}]},{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Import","marks":[{"type":"bold"}]},{"type":"text","text":". Three agreements are read at a time, each the same way "},{"type":"text","text":"Create from the agreement","marks":[{"type":"bold"}]},{"type":"text","text":" reads a single order, and each takes a minute or two. Keep the page open until the run finishes, or select "},{"type":"text","text":"Stop after the ones reading","marks":[{"type":"bold"}]},{"type":"text","text":". If the reading service asks the portal to slow down, the run pauses and carries on by itself."}]},{"type":"paragraph","content":[{"type":"text","text":"The manifest's facts win over what the document says; the schedule comes from the document. Each entry becomes a draft contract, which schedules nothing until someone activates it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Review"}]},{"type":"paragraph","content":[{"type":"text","text":"The batch page opens on "},{"type":"text","text":"Needs a look","marks":[{"type":"bold"}]},{"type":"text","text":": drafts where the document disagrees with the manifest, or where an instruction couldn't be saved as a schedule line. Open a row to see each disagreement side by side, and select "},{"type":"text","text":"Enter on the schedule","marks":[{"type":"bold"}]},{"type":"text","text":" for the lines to enter by hand. "},{"type":"text","text":"Ready to activate","marks":[{"type":"bold"}]},{"type":"text","text":" means nothing was flagged; the draft still needs a look before it's activated. A failed entry shows why; fix the cause and select "},{"type":"text","text":"Run again","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Running it again"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Importing again never creates a second contract for an entry that already has one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Loading a corrected manifest under the same batch name updates entries that haven't been imported. Keep each row's key the same."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"To redo an imported entry, delete its draft contract; the entry can then be imported again."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A document that has already been imported, under any entry, is not imported again."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-09-30-underwriting-legacy-copy',
  p_tool_key => 'underwriting',
  p_released_on => '2026-09-30',
  p_title => 'Active copy comes in from RadioTraffic',
  p_guide_slugs => array['underwriting-migrate-legacy-copy', 'underwriting-migrate-legacy-agreements'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Administrators can now bring active underwriting copy in from RadioTraffic, on a new Copy tab under Migrate legacy records. Each message is matched to its underwriter and to copy already in the portal by its script, and linked to a contract only where exactly one agreement fits. The few rows that need a decision are asked about first; nothing is written until you import, and running it again is safe."}]}]}$body$
);
